IDS = ["LY-%d" % i for i in range(614, 630)] + ["MH-001", "MH-002", "MH-003", "MH-006"]
sizes = []
for cid in IDS:
    d = P[cid]
    obj = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    path = os.path.join(OUT, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    sizes.append((cid, os.path.getsize(path)))

# verify: re-open each exactly
ok = 0
for cid in IDS:
    path = os.path.join(OUT, cid + ".json")
    with open(path, encoding="utf-8") as f:
        o = json.load(f)
    assert set(o.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, cid
    assert o["case_id"] == cid, cid
    assert set(o["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}, cid
    ok += 1
print("written+verified:", ok)
for cid, s in sizes:
    print(cid, s)
ly = [P[c] for c in IDS if c.startswith("LY-")]
print("trigger counts LY: changed_main=%d reserve_used=%d disputed=%d" % (
    sum(x["trigger"]["changed_main"] for x in ly),
    sum(x["trigger"]["reserve_used"] for x in ly),
    sum(x["trigger"]["disputed"] for x in ly)))
